import shutil
import subprocess
from pathlib import Path

import pytest

REPO_ROOT = Path(__file__).resolve().parents[1]


def _run_node(script: str) -> None:
    node = shutil.which("node")
    if node is None:
        pytest.skip("Node.js is required for demo client tests")
    subprocess.run(
        [node, "--input-type=module", "-e", script],
        cwd=REPO_ROOT,
        check=True,
        capture_output=True,
        text=True,
    )


def test_websocket_playback_buffer():
    _run_node('await import("./demo/tests/playback.test.mjs");')


def test_adapter_uses_stock_sdk_transport_for_each_mode():
    _run_node(
        """
globalThis.localStorage = { getItem() { return null; } };
globalThis.location = { href: "https://demo.test/" };
globalThis.CustomEvent = class CustomEvent extends Event {
  constructor(type, init = {}) { super(type); this.detail = init.detail; }
};
globalThis.Audio = class Audio { constructor() { this.autoplay = false; this.srcObject = null; } };

const sessions = [];
class Transport {
  constructor(options) { this.options = options; this.listeners = new Map(); }
  on(name, callback) { this.listeners.set(name, callback); }
  requestResponse() {}
}
class WebSocketTransport extends Transport {}
class WebRtcTransport extends Transport {}
class RealtimeAgent { constructor(options) { Object.assign(this, options); } }
class RealtimeSession {
  constructor(agent, options) {
    this.agent = agent;
    this.options = options;
    this.listeners = new Map();
    this.messages = [];
    sessions.push(this);
  }
  on(name, callback) { this.listeners.set(name, callback); }
  async connect(options) { this.connectOptions = options; }
  sendMessage(message) { this.messages.push(message); }
  mute() {}
  close() {}
}
globalThis.OpenAIAgentsRealtime = {
  OpenAIRealtimeWebSocket: WebSocketTransport,
  OpenAIRealtimeWebRTC: WebRtcTransport,
  RealtimeAgent,
  RealtimeSession,
  tool: (options) => options,
};

const { S2sRealtimeClient } = await import("./demo/s2s-realtime-client.js");
const micStream = { getAudioTracks() { return [{}]; } };
for (const [transport, url] of [
  ["websocket", "ws://example.test/v1/realtime"],
  ["webrtc", "api/calls"],
]) {
  const client = new S2sRealtimeClient({
    transport,
    directUrl: transport === "websocket" ? url : "",
    callsUrl: transport === "webrtc" ? url : "",
    voice: "coral",
    instructions: "Be concise.",
    startupGreeting: "Say hello.",
    micStream,
  });
  client._setupAudio = async () => {};
  client._attachRtcOutput = () => {};
  await client.connect();
  const session = sessions.at(-1);
  const expectedUrl = transport === "webrtc" ? "https://demo.test/api/calls" : url;
  if (session.connectOptions.url !== expectedUrl) throw new Error(`wrong ${transport} URL`);
  if (session.messages.join("|") !== "Say hello.") throw new Error("startup greeting missing");
  if (session.options.config.audio.input.format.rate !== 24000) throw new Error("input is not GA PCM 24 kHz");
  if (session.options.config.audio.output.format.rate !== 24000) throw new Error("output is not GA PCM 24 kHz");
  if (Object.hasOwn(session.options.config.audio.output, "voice")) {
    throw new Error("nested voice would pin live updates to the initial value");
  }
  if (session.agent.voice !== "coral") throw new Error("initial agent voice missing");
  if (transport === "websocket" && !(session.options.transport instanceof WebSocketTransport)) {
    throw new Error("WebSocket did not use the stock SDK transport");
  }
  if (transport === "webrtc" && !(session.options.transport instanceof WebRtcTransport)) {
    throw new Error("WebRTC did not use the stock SDK transport");
  }
}
"""
    )


def test_websocket_audio_setup_requires_the_versioned_24khz_worklet():
    _run_node(
        """
globalThis.window = globalThis;
globalThis.requestAnimationFrame = () => 1;
globalThis.document = { documentElement: { style: { setProperty() {}, removeProperty() {} } } };

const { AUDIO_WORKLET_VERSION, S2sRealtimeClient } = await import("./demo/s2s-realtime-client.js");

async function setupAudio(captureConfig) {
  const modules = [];
  const nodes = [];
  const analyser = () => ({
    fftSize: 0,
    smoothingTimeConstant: 0,
    frequencyBinCount: 128,
    connect() {},
    getByteFrequencyData() {},
  });
  const context = {
    state: "running",
    destination: {},
    audioWorklet: { async addModule(url) { modules.push(url); } },
    createMediaStreamSource() { return { connect() {} }; },
    createAnalyser: analyser,
  };
  globalThis.AudioWorkletNode = class AudioWorkletNode {
    constructor(_context, name, options) {
      this.name = name;
      this.options = options;
      this.messages = [];
      this.port = {
        onmessage: null,
        postMessage: (message) => {
          this.messages.push(message);
          if (name === "mic-capture" && message?.kind === "probe" && captureConfig !== undefined) {
            this.port.onmessage?.({ data: captureConfig });
          }
        },
      };
      nodes.push(this);
    }
    connect() {}
  };

  const client = new S2sRealtimeClient({
    transport: "websocket",
    directUrl: "ws://unused",
    audioContext: context,
    micStream: {},
  });
  await client._setupAudio();
  return { modules, nodes };
}

const good = await setupAudio({
  kind: "capture-config",
  inputRate: 48000,
  outputRate: 24000,
  version: AUDIO_WORKLET_VERSION,
});
const workletUrls = good.modules.map((url) => new URL(url));
const workletNames = workletUrls.map((url) => url.pathname.split("/").at(-1));
if (JSON.stringify(workletNames) !== JSON.stringify(["mic-capture.js", "audio-playback.js"])) {
  throw new Error(`unexpected audio worklets: ${JSON.stringify(good.modules)}`);
}
if (workletUrls.some((url) => url.searchParams.get("v") !== AUDIO_WORKLET_VERSION)) {
  throw new Error(`audio worklets were not versioned: ${JSON.stringify(good.modules)}`);
}
const capture = good.nodes.find((node) => node.name === "mic-capture");
if (capture?.options?.processorOptions?.targetRate !== 24000) {
  throw new Error("capture worklet was not configured for 24 kHz");
}

let mismatch;
try {
  await setupAudio({
    kind: "capture-config",
    inputRate: 48000,
    outputRate: 16000,
    version: "stale-16k",
  });
} catch (error) {
  mismatch = error;
}
if (!String(mismatch?.message).includes("sample-rate mismatch")) {
  throw new Error(`stale worklet was not rejected: ${mismatch}`);
}

const realSetTimeout = window.setTimeout;
window.setTimeout = (callback) => {
  queueMicrotask(callback);
  return 1;
};
let noConfig;
try {
  await setupAudio(undefined);
} catch (error) {
  noConfig = error;
} finally {
  window.setTimeout = realSetTimeout;
}
if (!String(noConfig?.message).includes("did not report")) {
  throw new Error(`non-reporting stale worklet was not rejected: ${noConfig}`);
}
"""
    )


def test_adapter_delegates_tools_to_realtime_session():
    _run_node(
        """
globalThis.localStorage = { getItem() { return null; } };
class RealtimeAgent { constructor(options) { Object.assign(this, options); } }
globalThis.OpenAIAgentsRealtime = {
  RealtimeAgent,
  tool: (options) => options,
};
const { S2sRealtimeClient } = await import("./demo/s2s-realtime-client.js");
const calls = [];
const images = [];
const client = new S2sRealtimeClient({
  transport: "websocket",
  directUrl: "ws://unused",
  voice: "coral",
  instructions: "Be concise.",
  tools: [{
    type: "function",
    name: "lookup",
    description: "Look up a value.",
    parameters: { type: "object", properties: { query: { type: "string" } } },
  }],
  async executeTool(call) {
    calls.push(call);
    return { output: "found", image: "data:image/jpeg;base64,AA==" };
  },
});
client._session = { addImage(image, options) { images.push([image, options]); } };
const agent = client._buildAgent();
const output = await agent.tools[0].execute(
  { query: "sdk" },
  undefined,
  { toolCall: { callId: "call_1" } },
);
if (output !== "found") throw new Error("tool output was not returned to RealtimeSession");
if (JSON.stringify(calls) !== JSON.stringify([{
  name: "lookup", arguments: '{"query":"sdk"}', callId: "call_1",
}])) throw new Error(`unexpected tool call: ${JSON.stringify(calls)}`);
if (images.length !== 1 || images[0][1].triggerResponse !== false) {
  throw new Error("tool image was not inserted before the SDK function output");
}
"""
    )


